"use strict";exports.id=46,exports.ids=[46],exports.modules={6046:(e,i,t)=>{t.d(i,{mE:()=>a,q5:()=>n,ux:()=>o});let n={clinic:{legalName:"TBD:clinic_legal_name",brandName:"TBD:clinic_brand",tagline:"TBD:clinic_brand",address:{street:"TBD:clinic_address",city:"Thane",state:"Maharashtra",country:"India",postalCode:"TBD:clinic_address",landmark:"TBD:clinic_address"},geo:{latitude:null,longitude:null,mapEmbedUrl:void 0},phone:"TBD:clinic_phone",email:"TBD:clinic_email",whatsapp:"TBD:clinic_whatsapp",hours:{regular:[{days:"Monday - Saturday",hours:"TBD:clinic_hours"},{days:"Sunday",hours:"TBD:clinic_hours"}],holidayNote:"TBD:clinic_hours",emergencyProtocol:"TBD:clinic_emergency_contacts"},story:"TBD:clinic_story",mission:"TBD:clinic_story",values:["Patient-first ethical clinical dentistry without commercial over-treatment.","Strict hospital-grade Class-B autoclaving and cross-infection prevention.","Complete cost transparency before any intervention commences.","Continuous clinical education and evidence-based treatment modalities."],facilities:["TBD:clinic_facilities","Ergonomic European dental delivery units with integrated intraoral cameras","Class-B vacuum autoclave with chemical indicator monitoring for 100% sterile tray setups","Digital low-radiation radiovisiography (RVG) and apex locators"],hygienePractices:["Hospital-grade 4-step sterilization: ultrasonic cleaning, enzymatic disinfection, pouching, and autoclave","Surface barrier films replaced between every patient visit","Hospital-grade air filtration in operatories","Personal Protective Equipment (PPE) protocol adhered to strictly"],licenses:["TBD:clinic_licenses"],emergencyContacts:{clinicHelpline:"TBD:clinic_phone",nearbyHospital:"TBD:clinic_emergency_contacts",ambulance:"108"}},services:[{slug:"root-canal-treatment",title:"Root Canal Treatment (Endodontics)",category:"Endodontics",shortDescription:"Precision rotary endodontic therapy designed to eliminate tooth infection and preserve natural dentition painlessly.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Root canal treatment is an endodontic procedure that removes infected or inflamed pulp tissue from within the root canals of a tooth. The canals are thoroughly disinfected, shaped with flexible nickel-titanium rotary instruments, and sealed hermetically with biocompatible gutta-percha to prevent reinfection.",indications:["Persistent throbbing toothache or nocturnal pain","Prolonged sensitivity to hot and cold temperatures","Pain during biting or chewing pressure","Facial swelling or gum abscess adjacent to tooth"],procedureSteps:["Clinical examination and diagnostic digital radiograph (RVG)","Profound local anaesthesia administration for total patient comfort","Isolation with dental rubber dam to ensure dry sterile field","Removal of decayed tooth structure and infected pulp tissue","Electronic apex locator measurement of canal lengths","Mechanical rotary instrumentation and antimicrobial irrigation","Hermetic warm vertical obturation (canal sealing)","Post-endodontic coronal restoration (composite core or crown)"],preCare:["Have a light meal prior to your appointment unless instructed otherwise.","Inform the clinician of all current medical conditions, allergies, and medications."],postCare:["Avoid chewing hard foods on the treated side until the permanent crown is placed.","Mild soreness for 24-48 hours is normal and managed with prescribed analgesic."],faqs:[{question:"Is root canal treatment painful?",answer:"With modern local anaesthesia and gentle rotary techniques, root canal treatment is typically as comfortable as receiving a routine dental filling."},{question:"How many sittings are required?",answer:"Many uncomplicated cases are completed in a single session. Severe infections with purulent discharge may require 2 visits with inter-appointment medication."}]},{slug:"dental-implants",title:"Single & Multi-Tooth Dental Implants",category:"Implantology",shortDescription:"Biocompatible titanium fixtures surgically placed into the jawbone to permanently replace missing tooth roots.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Dental implants represent the gold standard in tooth replacement. Composed of medical-grade titanium or zirconia, the fixture integrates naturally with jawbone tissue through osseointegration, providing a solid foundation for a bespoke ceramic crown.",indications:["Single or multiple missing teeth","Difficulty chewing or speaking due to tooth loss","Prevention of bone resorption in edentulous areas","Alternative to removable dentures or bridge preparation of healthy adjacent teeth"],procedureSteps:["CBCT 3D bone scan evaluation and digital treatment planning","Minimally invasive surgical placement of implant fixture","Healing period (osseointegration) of 8 to 16 weeks","Abutment connection and precision digital scan","Delivery and screw-retained or cement-retained porcelain crown"],preCare:["Complete medical review including HbA1c (diabetic check) and blood pressure.","Discontinue smoking as it significantly impairs osseointegration."],postCare:["Maintain soft diet for the initial 48 hours.","Apply cold compression externally to minimize mild postoperative swelling."],faqs:[{question:"What is the success rate of dental implants?",answer:"In healthy candidates with adequate bone volume and good oral hygiene, dental implants have an internationally documented success rate of 95% to 98%."}]},{slug:"laser-teeth-whitening",title:"Laser Teeth Whitening",category:"Cosmetic Dentistry",shortDescription:"In-office laser-activated tooth brightening for safe, dramatic aesthetic rejuvenation.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Professional in-chair whitening utilizes concentrated hydrogen or carbamide peroxide formulations activated by a calibrated dental laser or LED curing lamp. Enamel stains from tea, coffee, smoking, and age are gently oxidized without damaging tooth structure.",indications:["Extrinsic enamel staining from coffee, tea, wine, or tobacco","Generalized yellowing or dullness due to natural aging","Smile enhancement before weddings or key personal occasions"],procedureSteps:["Pre-whitening clinical shade assessment using VITA shade guide","Professional scaling and polishing to remove plaque and tartar","Gingival barrier resin application to protect gums completely","Application of professional whitening gel","Laser light activation in 15-minute cycles (typically 2-3 cycles)","Post-procedure desensitizing fluoride application"],preCare:["Ensure any active cavities or gum inflammation are treated before whitening."],postCare:["Adhere to the 'white diet' (no dark liquids, turmeric, coffee, tea, red wine) for 48 hours.","Use desensitizing toothpaste if temporary sensitivity occurs."],faqs:[{question:"Does whitening damage dental enamel?",answer:"No. Professional dentist-supervised whitening safely penetrates enamel prisms to oxidize pigment molecules without altering the mineral structure."}]},{slug:"braces-and-aligners",title:"Clear Aligners & Orthodontics",category:"Orthodontics",shortDescription:"Discreet transparent aligners and modern ceramic braces to correct malocclusion, crowding, and gaps.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Clear aligner therapy uses a series of custom-molded medical polyurethane trays engineered with CAD/CAM technology. Each tray applies calibrated micro-forces to move teeth gradually into ideal anatomical alignment.",indications:["Dental crowding and overlapping teeth","Diastema (spaces and gaps between teeth)","Overbite, underbite, or crossbite malocclusion","Adults seeking discreet alternatives to traditional metal brackets"],procedureSteps:["Comprehensive orthodontic photography and intraoral 3D scanning","Digital treatment simulation and clincheck review","Delivery of first set of custom clear aligners with wear instructions","Periodic clinical monitoring visits every 6 to 8 weeks","Post-treatment retention phase to lock permanent alignment"],preCare:["Complete routine scaling and cavity restorations before orthodontic setup."],postCare:["Wear aligners for 20 to 22 hours daily; remove only for meals and brushing.","Store aligners in protective case when eating."],faqs:[{question:"Can I eat while wearing clear aligners?",answer:"No. Aligners must be removed before consuming food or warm beverages to prevent staining and distortion of the thermoplastic material."}]},{slug:"smile-designing",title:"Smile Designing & Porcelain Veneers",category:"Cosmetic Dentistry",shortDescription:"Ultra-thin custom ceramic veneers crafted to balance proportions, color, and dental aesthetics.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Digital smile design harmonizes tooth form, shade, lip curvature, and facial symmetry. Ceramic veneers (E-max / feldspathic porcelain) are bonded to the facial surface of anterior teeth with minimal enamel preparation.",indications:["Chipped, worn, or unevenly shaped incisal edges","Intrinsic tetracycline or fluorosis staining resistant to bleaching","Slight gaps or irregular tooth contouring"],procedureSteps:["Facial aesthetic photography and digital mockup","Diagnostic wax-up and temporary trial smile in the mouth","Minimal conservative enamel preparation","High-definition digital impression and laboratory ceramic fabrication","Adhesive resin bonding under rubber dam isolation"],preCare:["Detailed smile goal discussion and digital mockup preview."],postCare:["Wear a protective night guard if you have nocturnal bruxism (teeth grinding).","Avoid biting directly on ice or hard bones with anterior veneers."],faqs:[{question:"How long do porcelain veneers last?",answer:"With good oral hygiene, regular 6-month checks, and proper care, high-quality porcelain veneers typically last 10 to 15 years."}]},{slug:"crowns-and-bridges",title:"Crowns & Fixed Partial Dentures",category:"Prosthodontics",shortDescription:"Full-coverage zirconia and ceramic restorations to restore broken, treated, or missing teeth.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Dental crowns encase the visible portion of damaged or endodontically treated teeth to restore structural integrity and masticatory function. Bridges replace one or more missing teeth by anchoring to sound adjacent teeth.",indications:["Fractured or severely broken down teeth","Endodontically treated teeth requiring coronal protection","Replacement of defective or discolored existing restorations"],procedureSteps:["Tooth preparation with smooth margins under magnification","Precise digital intraoral scanning","CAD/CAM milling of monolithic zirconia or porcelain-layered crown","Try-in for bite check, contact points, and shade verification","Permanent adhesive or resin luting cementation"],preCare:["Discuss shade matching and material choices with the dentist."],postCare:["Maintain diligent flossing around crown margins and bridge pontics."],faqs:[{question:"What is the difference between Zirconia and Metal-Ceramic?",answer:"Zirconia is 100% metal-free, biocompatible, and virtually unbreakable. Unlike metal-ceramic crowns, it eliminates black gum lines over time."}]},{slug:"pediatric-dentistry",title:"Pediatric & Preventive Dentistry",category:"Pediatric Dentistry",shortDescription:"Compassionate dental care for infants, children, and adolescents focusing on cavity prevention and positive experiences.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Specialized pediatric dentistry establishes early oral hygiene routines and prevents childhood dental decay through topical fluoride applications, pit and fissure sealants, and gentle behavioral guidance.",indications:["First dental visit (by age 1 or eruption of first tooth)","Early childhood caries / baby bottle tooth decay","Habit correction (thumb sucking, tongue thrusting)","Space maintainers for prematurely lost deciduous teeth"],procedureSteps:["Tell-Show-Do gentle introduction for child comfort","Painless clinical examination and cavity risk assessment","Topical fluoride varnish application or tooth-colored restorations","Dietary counseling and toothbrushing demonstration for parents"],preCare:["Schedule appointments during the child's alert hours (morning is optimal)."],postCare:["Refrain from eating for 30 minutes following fluoride varnish treatment."],faqs:[{question:"Why treat baby teeth if they will fall out anyway?",answer:"Deciduous teeth maintain space for permanent successors, assist in proper speech development, and enable healthy childhood nutrition."}]},{slug:"gum-treatment",title:"Periodontal Care & Gum Therapy",category:"Periodontics",shortDescription:"Ultrasonic scaling, deep root planning, and laser gum debridement to combat gingivitis and periodontitis.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Periodontal therapy targets bacterial biofilm and subgingival calculus deposits that cause gum inflammation, bleeding, bone loss, and tooth mobility. Ultrasonic scaling combined with subgingival curettage restores healthy pink gingiva.",indications:["Bleeding gums during toothbrushing or flossing","Persistent halitosis (bad breath)","Receding gum lines and elongated tooth appearance","Loose teeth or changes in dental occlusion"],procedureSteps:["Periodontal pocket depth charting and gingival index assessment","Full-mouth ultrasonic scaling to remove supragingival calculus","Deep subgingival root planning under topical or local anaesthetic","Antimicrobial subgingival irrigation","Re-evaluation visit after 4 to 6 weeks"],preCare:["Inform the dentist of any blood-thinning medications or systemic conditions."],postCare:["Use warm saline rinses and a soft-bristled toothbrush for 3 to 5 days."],faqs:[{question:"Does dental scaling loosen healthy teeth?",answer:"No. This is a common misconception. Scaling removes the hard bacterial tartar deposits. In advanced gum disease, removing tartar reveals preexisting bone loss."}]},{slug:"wisdom-tooth-removal",title:"Wisdom Tooth Removal & Minor Oral Surgery",category:"Oral Surgery",shortDescription:"Surgical management of impacted third molars, pericoronitis, and dental cysts with maximum comfort.",indicativePriceRange:"TBD:service_prices",indicativeDuration:"TBD:service_durations",overview:"Impacted wisdom teeth (third molars) that cannot erupt properly due to jaw arch space limitations often cause pain, decay in adjacent molars, and recurrent gum infections (pericoronitis). Surgical extraction safely removes problematic teeth under local anaesthesia.",indications:["Recurrent pain, swelling, or difficulty opening mouth (trismus)","Food impaction between wisdom tooth and adjacent second molar","Orthodontic crowding or cystic pathology on radiograph"],procedureSteps:["Panoramic OPG radiograph to evaluate inferior alveolar nerve relationship","Profound local anaesthesia block for complete numbness","Gentle mucosal reflection and conservative bone troughing","Tooth sectioning for atraumatic tooth removal","Surgical debridement and resorbable suturing"],preCare:["Have a nutritious meal prior to surgical appointment."],postCare:["Bite firmly on the sterile gauze pack for 45 minutes.","Do not spit, drink through a straw, or smoke for 24 hours to preserve the protective blood clot."],faqs:[{question:"What is dry socket and how is it prevented?",answer:"Dry socket occurs if the blood clot in the extraction site is dislodged prematurely. Following post-extraction guidelines strictly prevents this."}]}],dentists:[{id:"dentist-01",slug:"lead-prosthodontist",name:"TBD:dentist_roster",role:"Chief Dental Surgeon & Implantologist",qualifications:"TBD:dentist_credentials",specialization:"Prosthodontics, Implantology & Aesthetic Rehabilitation",experienceYears:"TBD:dentist_credentials",languages:["English","Hindi","Marathi"],consultationSchedule:"TBD:dentist_schedules",bio:"TBD:dentist_roster"},{id:"dentist-02",slug:"senior-endodontist",name:"TBD:dentist_roster",role:"Senior Consultant Endodontist",qualifications:"TBD:dentist_credentials",specialization:"Microscopic Endodontics & Rotary Root Canal Therapy",experienceYears:"TBD:dentist_credentials",languages:["English","Hindi","Marathi"],consultationSchedule:"TBD:dentist_schedules",bio:"TBD:dentist_roster"},{id:"dentist-03",slug:"consultant-orthodontist",name:"TBD:dentist_roster",role:"Consultant Orthodontist & Dentofacial Orthopedist",qualifications:"TBD:dentist_credentials",specialization:"Clear Aligners, Lingual Braces & Growth Modulation",experienceYears:"TBD:dentist_credentials",languages:["English","Hindi"],consultationSchedule:"TBD:dentist_schedules",bio:"TBD:dentist_roster"}],blogPosts:[{slug:"understanding-root-canal-therapy-facts-vs-myths",title:"Understanding Modern Root Canal Therapy: Facts vs Myths",category:"Oral Health Education",publishedAt:"2026-10-15",readTime:"5 min read",summary:"Explore why modern root canal therapy is virtually painless, how rotary instrumentation works, and why preserving your natural tooth is superior to extraction.",content:["Dental health myths often discourage patients from seeking timely endodontic care. A persistent throbbing toothache indicates that dental pulp—the soft neurovascular tissue at the centre of the tooth—has become infected by deep bacterial infiltration.","Rather than extraction, root canal treatment preserves the natural tooth root within the alveolar bone. Maintaining natural dentition preserves chewing efficiency, jawbone density, and prevents adjacent teeth from drifting out of alignment.","Modern endodontics incorporates electronic apex locators, high-torque rotary nickel-titanium files, and warm obturation techniques, making treatment comfortable and efficient."],authorName:"TBD:blog_content",clinicalReviewer:"TBD:blog_content",reviewedDate:"2026-10-14"},{slug:"clear-aligners-vs-traditional-braces-comprehensive-guide",title:"Clear Aligners vs Traditional Braces: The Complete Clinical Guide",category:"Orthodontics",publishedAt:"2026-10-28",readTime:"6 min read",summary:"A clinical comparison between transparent thermoplastic aligners and conventional brackets: comfort, aesthetics, oral hygiene, and treatment speed.",content:["Correcting dental malocclusion is not merely cosmetic—properly aligned teeth are significantly easier to clean, reducing the long-term risk of interproximal decay and periodontal disease.","Clear aligners offer distinct lifestyle benefits: they are virtually invisible from conversational distances and can be removed during meals and oral hygiene routines.","However, successful clear aligner therapy demands diligent patient compliance: trays must be worn consistently for 20 to 22 hours per day to achieve planned tooth movements."],authorName:"TBD:blog_content",clinicalReviewer:"TBD:blog_content",reviewedDate:"2026-10-27"},{slug:"preventing-gum-disease-daily-protocol",title:"Preventing Periodontal Disease: Daily Protocol & Early Warning Signs",category:"Preventive Care",publishedAt:"2026-11-05",readTime:"4 min read",summary:"Learn how biofilm matures into tartar, why bleeding gums should never be ignored, and the daily evidence-based routine to maintain healthy gums.",content:["Gingivitis is the reversible precursor to periodontitis. When plaque remains on teeth for more than 48 hours, it begins to mineralize into dental calculus (tartar), which cannot be removed by brushing alone.","Healthy gums do not bleed during normal brushing or flossing. If you observe pink in the sink, it signifies underlying bacterial inflammation requiring professional ultrasonic debridement.","Daily flossing or interdental brushes, paired with 6-monthly professional cleanings, remain the most cost-effective investment in lifelong dental health."],authorName:"TBD:blog_content",clinicalReviewer:"TBD:blog_content",reviewedDate:"2026-11-04"}],gallery:[{id:"gal-01",title:"Anterior Smile Rejuvenation with E-max Porcelain Veneers",treatmentSlug:"smile-designing",category:"Cosmetic",description:"Restoration of incisal wear and intrinsic discoloration using 6 minimal-preparation ceramic veneers.",consentRecorded:!0,consentReferenceId:"CONSENT-MED-2026-0812",beforeLabel:"Pre-Treatment: Incisal chipping, uneven proportions and staining",afterLabel:"Post-Treatment: Harmonized incisal contour and natural vitality",clinicalNotes:"Case documented with full clinical consent for healthcare education. Individual clinical outcomes vary."},{id:"gal-02",title:"Clear Aligner Crowding Correction",treatmentSlug:"braces-and-aligners",category:"Orthodontics",description:"Resolution of moderate lower anterior crowding and midline discrepancy over a 9-month aligner protocol.",consentRecorded:!0,consentReferenceId:"CONSENT-MED-2026-0945",beforeLabel:"Pre-Treatment: Lower anterior crowding with plaque retention risk",afterLabel:"Post-Treatment: Anatomical alignment facilitating easy flossing",clinicalNotes:"Patient consent verified under DPDP Act purpose-specific image guidelines."},{id:"gal-03",title:"Single Molar Implant Restoration",treatmentSlug:"dental-implants",category:"Implantology",description:"Replacement of fractured first molar with a screw-retained monolithic zirconia crown on titanium fixture.",consentRecorded:!0,consentReferenceId:"CONSENT-MED-2026-1011",beforeLabel:"Pre-Treatment: Edentulous space with emerging adjacent tooth tilt",afterLabel:"Post-Treatment: Full functional occlusion restored without touching adjacent teeth",clinicalNotes:"Documented with patient written consent for clinical portfolio display."},{id:"gal-04-unconsented",title:"Unconsented Sample Case (Must Not Render)",treatmentSlug:"laser-teeth-whitening",category:"Cosmetic",description:"This item has no recorded consent and MUST be filtered out by the public gallery renderer.",consentRecorded:!1,beforeLabel:"Hidden",afterLabel:"Hidden",clinicalNotes:"Internal review only."}],testimonials:[{id:"tst-01",patientInitials:"R. S.",treatment:"Root Canal Treatment",reviewText:"The team explained every step of the root canal beforehand. I felt completely comfortable throughout the visit.",consentRecorded:!0,consentReferenceId:"CONSENT-TST-2026-01",verifiedVisitDate:"September 2026"},{id:"tst-02",patientInitials:"A. P.",treatment:"Clear Aligners",reviewText:"The 3D digital scan made the whole orthodontic planning seamless. Transparent pricing with zero hidden charges.",consentRecorded:!0,consentReferenceId:"CONSENT-TST-2026-02",verifiedVisitDate:"October 2026"},{id:"tst-03-unconsented",patientInitials:"M. K.",treatment:"Dental Implants",reviewText:"This testimonial has no consent and must never appear in the public UI.",consentRecorded:!1,verifiedVisitDate:"November 2026"}],faqs:[{category:"Appointments & Consultation",question:"How do I schedule an appointment?",answer:"You can book directly using our website's 'Book Appointment' button, selecting your preferred treatment, date, and time slot. Our clinic reception confirms all bookings after verifying operatory availability."},{category:"Appointments & Consultation",question:"What is your cancellation and rescheduling policy?",answer:"We kindly request at least 24 hours prior notice if you need to reschedule or cancel an appointment so that the operatory slot can be made available to patients requiring emergency care."},{category:"Treatments & Clinical Care",question:"How does the clinic ensure sterilization and patient safety?",answer:"We adhere to hospital-grade sterilization protocols including ultrasonic cleaning, medical-grade chemical disinfection, Class-B vacuum autoclaving of all surgical instruments in individual sealed pouches, and surface barrier replacements between every patient."},{category:"Fees & Payment",question:"Are indicative prices provided on the website final?",answer:"No. Website prices are strictly indicative estimates. Every human anatomy is unique. A finalized, itemized treatment estimate is provided only after an in-person clinical examination and diagnostic radiograph by our dental surgeon."},{category:"Fees & Payment",question:"What payment methods are accepted at the clinic?",answer:"We accept UPI, major credit/debit cards, net banking, and cash for all clinical consultations and procedures."},{category:"Emergency & Urgency",question:"What constitutes a dental emergency requiring immediate attention?",answer:"Severe trauma/knocked-out tooth (avulsion), persistent hemorrhage, rapidly spreading facial swelling impairing breathing or swallowing, and acute fever paired with tooth infection are red-flag emergencies requiring urgent in-person medical/dental care."}],policies:{privacyNotice:"TBD:privacy_notice",termsAndConditions:"TBD:terms",cancellationPolicy:"TBD:cancellation_policy"}};function a(e=n.gallery){return e.filter(e=>!0===e.consentRecorded&&!!e.consentReferenceId)}function o(e=n.testimonials){return e.filter(e=>!0===e.consentRecorded&&!!e.consentReferenceId)}}};